package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Locale;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PersonService {

    /** A person's statements: how many were taken, and the last one (null: none). */
    public record Statements(int count, Statement last) {
        public static final Statements NONE = new Statements(0, null);
    }

    /** A patron as a person's row shows them: their id and name. */
    public record PatronOf(long id, String name) {}

    private final PersonRepository people;
    private final StatementRepository statements;
    private final PatronRepository patrons;
    private final SheetService sheets;
    private final RollupService rollups;
    private final Audit audit;

    public PersonService(PersonRepository people, StatementRepository statements, PatronRepository patrons,
            SheetService sheets, RollupService rollups, Audit audit) {
        this.people = people;
        this.statements = statements;
        this.patrons = patrons;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's people, in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Each person's statements on the sheet, by person id; a person with none is absent. */
    @Transactional(readOnly = true)
    public Map<Long, Statements> statements(String sheetId) {
        Map<Long, Statements> out = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            out.merge(s.getPersonId(), new Statements(1, s), (was, now) -> new Statements(was.count() + 1, s));
        }
        return out;
    }

    /** Each person's patrons on the sheet, sorted by name, by person id; a person with none is absent. */
    @Transactional(readOnly = true)
    public Map<Long, List<PatronOf>> patrons(String sheetId) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PatronOf>> out = new HashMap<>();
        for (Patron link : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
            Person patron = byId.get(link.getPatronId());
            if (patron == null) continue;
            out.computeIfAbsent(link.getPersonId(), id -> new ArrayList<>())
                    .add(new PatronOf(patron.getId(), patron.getName()));
        }
        out.values().forEach(list -> list.sort(Comparator.comparing(PatronOf::name)));
        return out;
    }

    /**
     * Name another person on the sheet as a person's patron: refused for the person themselves and for
     * one already named.
     */
    @Transactional
    public Person addPatron(String sheetId, String user, long personId, long patronId) {
        sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron"));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) throw patronNamed();
        try {
            patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException e) {
            throw patronNamed();
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " patron=" + patron.getName());
        return person;
    }

    /** Add a person (the sheet is started when it was never loaded before). */
    @Transactional
    public Person add(String sheetId, String user, String name, Grade grade) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        requireUnusedName(sheetId, null, trimmed);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        Person saved;
        try {
            saved = people.saveAndFlush(new Person(sheetId, trimmed, grade));
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit(sheetId, user, "PERSON_ADDED", saved, grade);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Change a person's name, and give them a grade from a date (the sheet's today when none is given),
     * keeping the grades already recorded; from the version of them the editor loaded: refused when
     * someone else has saved them since.
     */
    @Transactional
    public Person edit(String sheetId, String user, long personId, long version, String name, Grade grade,
            LocalDate gradeFrom) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getVersion() != version) throw editedMeanwhile();
        String trimmed = name.trim();
        requireUnusedName(sheetId, personId, trimmed);
        RollupService.Rollup before = rollups.snapshot(sheetId);
        person.setName(trimmed);
        person.setGradeFrom(grade, gradeFrom != null ? gradeFrom : sheets.today(sheetId));
        Person saved;
        try {
            saved = people.saveAndFlush(person);
        } catch (ObjectOptimisticLockingFailureException e) {
            throw editedMeanwhile();
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        }
        audit(sheetId, user, "PERSON_EDITED", saved, grade);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    /** Retire a person from a date (the sheet's today when none is given). */
    @Transactional
    public Person retire(String sheetId, String user, long personId, LocalDate from) {
        sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate dated = from != null ? from : sheets.today(sheetId);
        person.setRetiredFrom(dated);
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + dated);
        return saved;
    }

    /**
     * Put a person on hold from a date (the sheet's today when none is given) to a date (none:
     * open-ended), keeping their other holds; refused when it ends before it starts. Followed by the
     * rollup lines of the figures it moves (their open claims dated within it leave the live totals).
     */
    @Transactional
    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
        sheets.lock(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate dated = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(dated)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts");
        }
        RollupService.Rollup before = rollups.snapshot(sheetId);
        person.addHold(dated, to);
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + dated);
        rollups.recordChanges(sheetId, user, before);
        return saved;
    }

    private void audit(String sheetId, String user, String event, Person person, Grade grade) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " grade=" + grade);
    }

    /** Refuse a name another person on the sheet already has, ignoring case. */
    private void requireUnusedName(String sheetId, Long personId, String name) {
        String key = name.toLowerCase(Locale.ROOT);
        boolean used = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .anyMatch(p -> !p.getId().equals(personId) && p.getName().toLowerCase(Locale.ROOT).equals(key));
        if (used) throw nameInUse();
    }

    private static ResponseStatusException editedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Someone else has saved this person since");
    }

    private static ResponseStatusException patronNamed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That patron is already named");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use");
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

/** A person on a sheet. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades they were given, each from its date; the first one from the beginning of time. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** Retired from this date (claims dated after it are refused); null when not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Their holds: their open claims dated within one, not bound by a statement, count in no live total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {}

    public Person(String sheetId, String name, Grade grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(grade, null));
    }

    public Long getId() { return id; }

    public long getVersion() { return version; }

    public String getSheetId() { return sheetId; }

    public String getName() { return name; }

    public void setName(String name) { this.name = name; }

    /** The grades they were given, by from-date (the one from the beginning of time first). */
    public List<GradeFrom> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it. */
    public Grade gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> g.appliesOn(date))
                .max(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(GradeFrom::getGrade)
                .orElseThrow();
    }

    /** Give them a grade from a date, replacing the one they had from that date; the others are kept. */
    public void setGradeFrom(Grade grade, LocalDate from) {
        grades.removeIf(g -> Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(grade, from));
    }

    public LocalDate getRetiredFrom() { return retiredFrom; }

    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }

    /** Their holds, by from-date (one from the beginning of time first). */
    public List<Hold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(Hold::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Whether they have any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }

    /** Whether a hold of theirs covers {@code date}. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.covers(date)); }

    public void addHold(LocalDate from, LocalDate to) { holds.add(new Hold(from, to)); }

    /** Whether a claim dated {@code date} is after their retirement. */
    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date.isAfter(retiredFrom); }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A hold on a person, from a date (none: the beginning of time) to a date (none: open-ended), both days in. */
@Embeddable
public class Hold {

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected Hold() {}

    public Hold(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public LocalDate getFromDate() { return fromDate; }

    public LocalDate getToDate() { return toDate; }

    /** Whether {@code date} is within it. */
    public boolean covers(LocalDate date) {
        return (fromDate == null || !date.isBefore(fromDate)) && (toDate == null || !date.isAfter(toDate));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
