package net.officefloor.hq.app.settings;


/** The sheet's settings (its clerk limit, floor, terms, terms per grade, late percent, policy date and period numbering from-date) and the roles it gives user names. */
@Service
public class SettingsService {

    private final SheetRoleRepository roles;
    private final SheetService sheets;
    private final RollupService rollups;
    private final Audit audit;

    public SettingsService(SheetRoleRepository roles, SheetService sheets, RollupService rollups, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's settings now. */
    @Transactional
    public Sheet settings(String sheetId, String user) {
        return sheets.load(sheetId, user);
    }

    /**
     * Save the settings given: {@code setClerkLimit} the clerk limit (null: no limit), a non-null
     * {@code floor} the floor, a non-null {@code terms} the terms in days, each grade in {@code gradeTerms}
     * its own terms in days (null: it uses the sheet's terms), a non-null {@code latePct} the
     * late percent, {@code setPolicyDate} the policy date (null: the sheet's today), {@code setPeriodNumberingFrom}
     * the period numbering from-date (null: off); each one saved is
     * audited, even when its value is the same. A floor, terms, late percent or policy date that moves
     * dues records the rollups that moved.
     */
    @Transactional
    public Sheet save(String sheetId, String user, boolean setClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
            Integer terms, Map<Grade, Integer> gradeTerms, BigDecimal latePct, boolean setPolicyDate, LocalDate policyDate,
            boolean setPeriodNumberingFrom, LocalDate periodNumberingFrom) {
        Sheet sheet = sheets.lock(sheetId, user);
        if (setClerkLimit) {
            sheet.setClerkLimit(clerkLimit);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=clerk-limit value=" + (clerkLimit == null ? "" : clerkLimit.toPlainString()));
        }
        if (floor != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setFloor(floor);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=floor value=" + floor.toPlainString());
            rollups.recordChanges(sheetId, user, before);
        }
        if (terms != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setTerms(terms);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=terms value=" + terms);
            rollups.recordChanges(sheetId, user, before);
        }
        for (Grade grade : Grade.values()) {
            if (!gradeTerms.containsKey(grade)) continue;
            Integer days = gradeTerms.get(grade);
            sheet.setGradeTerms(grade, days);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=terms-" + grade + " value=" + (days == null ? "" : days));
        }
        if (latePct != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setLatePct(latePct);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=late-pct value=" + latePct.toPlainString());
            rollups.recordChanges(sheetId, user, before);
        }
        if (setPolicyDate) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setPolicyDate(policyDate);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=policy-date value=" + (policyDate == null ? "" : policyDate));
            rollups.recordChanges(sheetId, user, before);
        }
        if (setPeriodNumberingFrom) {
            sheet.setPeriodNumberingFrom(periodNumberingFrom);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=period-numbering-from value=" + (periodNumberingFrom == null ? "" : periodNumberingFrom));
        }
        return sheet;
    }

    /** The roles the sheet gives user names, by name; a name not among them is a clerk. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role the sheet gives a user name; clerk when it gives none. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Give a user name a role, replacing the one it had. */
    @Transactional
    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
        sheets.lock(sheetId, user);
        SheetRole entry = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new SheetRole(sheetId, userName, role));
        entry.setRole(role);
        SheetRole saved = roles.saveAndFlush(entry);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + userName + " role=" + role.name().toLowerCase());
        return saved;
    }
}
package net.officefloor.hq.app.settings;

/** The role a sheet gives a user name; a name with none is a clerk. */
public enum Role {
    /** May settle a claim only when its due is at or below the sheet's clerk limit. */
    CLERK,
    /** May settle any claim. */
    STEWARD
}
package net.officefloor.hq.app.sheet;


/** A sheet: the unit everything else in the app is kept under. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's "today": every date-dependent decision in the sheet uses it, never the clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number the sheet gave out; the next opened claim gets one more. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** A clerk may settle a claim only when its due is at or below this; none: no limit. */
    @Column(name = "clerk_limit", precision = 15, scale = 2)
    private BigDecimal clerkLimit;

    /** A claim's live due is at least this; a fixed, bound or closed-period figure is not changed by it. */
    @Column(name = "floor", nullable = false, precision = 15, scale = 2)
    private BigDecimal floor = new BigDecimal("1.00");

    /** A claim is due by its date plus this many days. */
    @Column(name = "terms", nullable = false)
    private int terms = 14;

    /** The terms of a grade that has its own; a grade without uses the sheet's terms. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_grade_terms", joinColumns = @JoinColumn(name = "sheet_id"))
    @MapKeyColumn(name = "grade")
    @MapKeyEnumerated(EnumType.STRING)
    @Column(name = "terms", nullable = false)
    private Map<Grade, Integer> gradeTerms = new HashMap<>();

    /** An overdue claim gains this percent of its figure for every full 30 days it is overdue. */
    @Column(name = "late_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal latePct = new BigDecimal("0.00");

    /** A claim dated before this rounds half up, one on or after it half to even; none: the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /**
     * While set and the sheet's today is on or after it, a claim opened is numbered within its period;
     * none: off, the sheet-wide sequence is used.
     */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {}

    public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = today;
    }

    public String getId() { return id; }

    public String getCreatedBy() { return createdBy; }

    public Instant getCreatedAt() { return createdAt; }

    public LocalDate getToday() { return today; }

    public void setToday(LocalDate today) { this.today = today; }

    public BigDecimal getClerkLimit() { return clerkLimit; }

    public void setClerkLimit(BigDecimal clerkLimit) { this.clerkLimit = clerkLimit; }

    public BigDecimal getFloor() { return floor; }

    public void setFloor(BigDecimal floor) { this.floor = floor; }

    public int getTerms() { return terms; }

    public void setTerms(int terms) { this.terms = terms; }

    /** The terms each grade with its own has. */
    public Map<Grade, Integer> getGradeTerms() {
        return Collections.unmodifiableMap(gradeTerms);
    }

    /** Give a grade its own terms; null: it uses the sheet's terms. */
    public void setGradeTerms(Grade grade, Integer days) {
        if (days == null) gradeTerms.remove(grade);
        else gradeTerms.put(grade, days);
    }

    /** The terms in force for a grade: its own, else the sheet's. */
    public int termsFor(Grade grade) { return gradeTerms.getOrDefault(grade, terms); }

    public BigDecimal getLatePct() { return latePct; }

    public void setLatePct(BigDecimal latePct) { this.latePct = latePct; }

    public LocalDate getPolicyDate() { return policyDate; }

    public void setPolicyDate(LocalDate policyDate) { this.policyDate = policyDate; }

    /** The policy date in force: the one set, else the sheet's today. */
    public LocalDate policyDateInForce() { return policyDate != null ? policyDate : today; }

    public LocalDate getPeriodNumberingFrom() { return periodNumberingFrom; }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) { this.periodNumberingFrom = periodNumberingFrom; }

    /** Whether a claim opened now is numbered within its period. */
    public boolean numbersByPeriod() { return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom); }

    /** Give out the sheet's next claim number. */
    public int takeClaimNumber() { return ++lastClaimNumber; }
}
package net.officefloor.hq.app.sheet;


@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollups;

    public SheetService(SheetRepository sheets, RollupService rollups) {
        this.sheets = sheets;
        this.rollups = rollups;
    }

    /** The sheet with this id; a sheet never loaded before is started empty, today at the real date. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /**
     * The sheet's "today". Every decision that depends on the date, and every default date, uses
     * this and never the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /**
     * Change the sheet's "today" (the sheet is started when it was never loaded before). It has no
     * audit line of its own, but is followed by the rollup lines of the figures it moves.
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = lock(id, user);
        RollupService.Rollup before = rollups.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        rollups.recordChanges(id, user, before);
        return sheet;
    }

    /**
     * Lock the sheet until the current transaction ends, so its claims' statuses change one at a
     * time (the sheet is started when it was never loaded before).
     */
    @Transactional
    public Sheet lock(String id, String user) {
        return sheets.findByIdForUpdate(id).orElseGet(() -> {
            load(id, user);
            return sheets.findByIdForUpdate(id).orElseThrow();
        });
    }
}
