  /** The figure it had at that statement, as text with two decimals; null when it had none (n/a). */
  statedDue: string | null;
  /** A correction's (negative amount) number of the settled claim of the same person it corrects; null otherwise. */
  corrects: string | null;
  /** One line per status it has had, oldest first (its DRAFT one written when it was added). */
  log: ClaimLogLine[];
}

/** A status a claim took, who gave it, the sheet's today then (yyyy-MM-dd) and its due then (text with two decimals; null: n/a). */
export interface ClaimLogLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

/** What a bulk open did: how many claims were opened and how many refused. */
export interface BulkOpened {
  opened: number;
  refused: number;
}

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A change of status a claim's buttons ask for (a steward approves or rejects a pending one). */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject';

/** A claim counts as open while it is open or pending a steward's approval. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Only open (pending ones among them) and settled claims count toward claimed and due; drafts and voided claims do not. */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/** Whether a statement binds the claim now: a pending one is not bound (its figure is live). */
function bound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

/** A claim keeps a figure that does not follow the rates: settled with a fixed due, or bound by a statement to one (not n/a). */
export function fixed(c: Claim): boolean {
  return c.due !== null || (bound(c) && c.statedDue !== null);
}

/** What an overdue claim's late charge follows: the sheet's today (yyyy-MM-dd; null: none loaded) and the late percent (in hundredths of a percent). */
export interface LateTerms {
  today: string | null;
  pct: number;
}

/**
 * A claim's due in cents: a settled claim's fixed figure (any late charge frozen in), else the figure
 * its person's last statement bound it to, otherwise its amount times the rate in force on its date
 * (looked up by `rateOn`, in hundredths of a percent), raised to the sheet's floor (in cents) unless a correction;
 * undefined when it has none. An overdue claim's figure gains its late charge on top (never bound).
 * Its live figures round half up when `halfUp` says so for it, else half to even.
 */
export function claimDue(
  c: Claim, rateOn: (date: string) => number | undefined, floor: number, late?: LateTerms,
  halfUp: (c: Claim) => boolean = () => false,
): number | undefined {
  if (c.due !== null) return cents(c.due);
  const up = halfUp(c);
  const figure = baseDue(c, rateOn, floor, up);
  return figure === undefined || !late || correction(c) ? figure : figure + lateCharge(c, figure, late, up);
}

function baseDue(
  c: Claim, rateOn: (date: string) => number | undefined, floor: number, halfUp: boolean,
): number | undefined {
  if (bound(c)) return c.statedDue === null ? undefined : cents(c.statedDue);
  const rate = rateOn(c.date);
  if (rate === undefined) return undefined;
  const d = due(cents(c.amount), rate, halfUp);
  return correction(c) ? d : Math.max(d, floor);
}

/** A correction: a negative amount; its due has no floor and no late charge. */
export function correction(c: Claim): boolean {
  return c.amount.startsWith('-');
}

/** The late charge in cents on a figure: the late percent of it for every full 30 days the claim is overdue, rounded like due. */
export function lateCharge(c: Claim, figure: number, late: LateTerms, halfUp = false): number {
  if (late.today === null || !overdue(c, late.today)) return 0;
  const days = (Date.parse(late.today) - Date.parse(c.dueBy)) / 86_400_000;
  return due(figure, late.pct * Math.floor(days / 30), halfUp);
}

/** A claim is overdue when it is open (or pending) and its due-by is before the sheet's today (yyyy-MM-dd; null: none loaded). */
export function overdue(c: Claim, today: string | null): boolean {
  return today !== null && isOpen(c) && c.dueBy < today;
}

export interface ClaimForm {
  amount: string;
  /** null: the sheet's today. */
  date: string | null;
  note: string;
  /** For a correction (a negative amount): the number of the settled claim it corrects. */
  corrects: string | null;
}

// The active sheet's claims, newest first, and what they add up to (kept in cents so sums are exact).
@Injectable({ providedIn: 'root' })
export class ClaimsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly people = inject(PeopleService);
  private readonly list = signal<Claim[]>([]);

  readonly claims = this.list.asReadonly();

  /** The ids of the claims chosen for a bulk open. */
  readonly selected = signal<ReadonlySet<number>>(new Set());

  /** Choose a claim for a bulk open, or leave it out. */
  select(claimId: number, on: boolean): void {
    this.selected.update((all) => {
      const out = new Set(all);
      if (on) out.add(claimId);
      else out.delete(claimId);
      return out;
    });
  }

  /** Each held person's holds, by person id. */
  private readonly holds = computed(
    () => new Map(this.people.people().filter((p) => p.holds.length > 0).map((p) => [p.id, p.holds])),
  );

  /**
   * Whether a claim counts in the live totals: open (pending ones among them) and settled ones do,
   * except a person's open ones dated within a hold of theirs; one bound by a statement counts whatever its date.
   */
  readonly live = computed(() => {
    const holds = this.holds();
    return (c: Claim) => counts(c)
      && !(isOpen(c) && !bound(c) && (holds.get(c.personId) ?? []).some((h) => holdCovers(h, c.date)));
  });

  /** Each person's claims, newest first. */
  readonly byPerson = computed(() => {
    const out = new Map<number, Claim[]>();
    for (const c of this.list()) out.set(c.personId, [...(out.get(c.personId) ?? []), c]);
    return out;
  });

  /** Each person's claimed (live claims), in cents. */
  readonly claimedCents = computed(() => {
    const out = new Map<number, number>();
    for (const c of this.list().filter(this.live())) out.set(c.personId, (out.get(c.personId) ?? 0) + cents(c.amount));
    return out;
  });

  /** Everyone's claimed (live claims) added up, in cents. */
  readonly totalCents = computed(() => this.list().filter(this.live()).reduce((sum, c) => sum + cents(c.amount), 0));

  /**
   * The date a claim rounds by: a correction's is the date of the claim it corrects (its own when
   * that is not found), any other claim's its own.
   */
  readonly roundingDate = computed(() => {
    const byNumber = new Map<string, string>();
    for (const c of this.list()) if (c.number !== null) byNumber.set(`${c.personId}:${c.number}`, c.date);
    return (c: Claim) => (c.corrects === null ? c.date : byNumber.get(`${c.personId}:${c.corrects}`) ?? c.date);
  });

  /** Re-read the active sheet's claims from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Claim[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((claims) => {
        if (this.sheets.sheetId() !== id) return;
        this.list.set(claims);
        const ids = new Set(claims.map((c) => c.id));
        this.selected.update((all) => new Set([...all].filter((c) => ids.has(c))));
      }));
  }

  add(personId: number, form: ClaimForm): Observable<Claim> {
    const sheet = this.sheet();
    return this.http
      .post<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/claims`, form, {
        headers: this.session.headers(),
      })
      .pipe(tap((c) => this.list.update((all) => [c, ...all])));
  }

  /**
   * Add a draft claim of this amount, dated the sheet's today, for the person with this name; one
   * not on the sheet is added first with grade A. The caller re-reads the people.
   */
  quickAdd(name: string, amount: string): Observable<Claim> {
    const sheet = this.sheet();
    return this.http
      .post<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, {
        headers: this.session.headers(),
      })
      .pipe(tap((c) => this.list.update((all) => [c, ...all])));
  }

  /** Take a statement for a person, binding their counting claims; the caller re-reads the people. */
  statement(personId: number): Observable<Claim[]> {
    const sheet = this.sheet();
    return this.http
      .post<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/people/${personId}/statement`, null, {
        headers: this.session.headers(),
      })
      .pipe(tap((theirs) => {
        const byId = new Map(theirs.map((c) => [c.id, c]));
        this.list.update((all) => all.map((o) => byId.get(o.id) ?? o));
      }));
  }

  edit(claimId: number, form: ClaimForm): Observable<Claim> {
    return this.http
      .put<Claim>(`${this.url(this.sheet())}/${claimId}`, form, { headers: this.session.headers() })
      .pipe(tap((c) => this.list.update((all) => all.map((o) => (o.id === c.id ? c : o)))));
  }

  /** Open, settle, void, approve or reject (with its reason) a claim. */
  changeStatus(claimId: number, action: ClaimAction, reason?: string): Observable<Claim> {
    const body = action === 'reject' ? { reason } : null;
    return this.http
      .post<Claim>(`${this.url(this.sheet())}/${claimId}/${action}`, body, { headers: this.session.headers() })
      .pipe(tap((c) => this.list.update((all) => all.map((o) => (o.id === c.id ? c : o)))));
  }

  /** Move a claim to another person (a steward); it is live again until their next statement. */
  reassign(claimId: number, personId: number): Observable<Claim> {
    return this.http
      .post<Claim>(`${this.url(this.sheet())}/${claimId}/reassign`, { personId }, { headers: this.session.headers() })
      .pipe(tap((c) => this.list.update((all) => all.map((o) => (o.id === c.id ? c : o)))));
  }

  /** Open the chosen claims that can be opened, numbered in list order; then re-read the claims. */
  bulkOpen(claimIds: readonly number[]): Observable<BulkOpened> {
    return this.http
      .post<BulkOpened>(`${this.url(this.sheet())}/bulk-open`, { claimIds }, { headers: this.session.headers() })
      .pipe(switchMap((r) => this.reload().pipe(map(() => r))));
  }

  private sheet(): string {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return id;
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/claims`;
  }
}

/** "12.34" as 1234. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const out = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
  return negative ? -out : out;
}

/** 1234 as "12.34". */
export function money(cents: number): string {
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, of, tap } from 'rxjs';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export type Grade = 'A' | 'B' | 'C';

export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

/** A hold on a person, from a date to a date (yyyy-MM-dd; null from: the beginning of time; null to: open-ended), both days in. */
export interface Hold {
  from: string | null;
  to: string | null;
}

/** Whether a hold covers a date (yyyy-MM-dd). */
export function holdCovers(h: Hold, date: string): boolean {
  return (h.from === null || h.from <= date) && (h.to === null || date <= h.to);
}

/** A grade a person was given, from a date (yyyy-MM-dd; null: from the beginning of time). */
export interface GradeFrom {
  grade: Grade;
  from: string | null;
}

export interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today. */
  grade: Grade;
  /** Every grade they were given, by from-date; the first one from the beginning of time. */
  grades: GradeFrom[];
  /** Moved on by every save; an edit names the version it was made from. */
  version: number;
  /** How many statements were taken for them. */
  statementCount: number;
  /** The last statement's due-total, as text with two decimals ("n/a" when it had none); null before the first. */
  statedTotal: string | null;
  /** The sheet's today (yyyy-MM-dd) when the last statement was taken; null before the first. */
  statementDate: string | null;
  /** Retired from this date (yyyy-MM-dd): claims dated after it are refused; null when not retired. */
  retiredFrom: string | null;
  /** Has any hold, whatever its dates. */
  held: boolean;
  /** Their holds, by from-date: their open claims dated within one, not bound by a statement, count in no live total. */
  holds: Hold[];
  /** The other people on the sheet they have named as patrons, sorted by name. */
  patrons: Patron[];
}

export interface Patron {
  id: number;
  name: string;
}

export interface PersonForm {
  name: string;
  grade: Grade;
  /** An edit gives the grade from this date (yyyy-MM-dd); the first grade applies from the beginning of time. */
  gradeFrom?: string;
}

/** The grade in force on a date (yyyy-MM-dd): the one given with the latest from-date on or before it. */
export function gradeOn(grades: readonly GradeFrom[], date: string): Grade | undefined {
  let best: GradeFrom | undefined;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (best === undefined || (best.from ?? '') < (g.from ?? '')) best = g;
  }
  return best?.grade;
}

// The active sheet's people, in the order they were added.
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Person[]>([]);

  readonly people = this.list.asReadonly();
  /** Whether retired people are listed: off when the screen opens, left as it is by loading a sheet. */
  readonly showRetired = signal(false);

  /** Re-read the active sheet's people from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Person[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((people) => {
        if (this.sheets.sheetId() === id) this.list.set(people);
      }));
  }

  add(form: PersonForm): Observable<Person> {
    return this.http
      .post<Person>(this.url(this.sheet()), form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => [...all, p])));
  }

  /** Save the person from the version the editor loaded; refused (412) when someone saved them since. */
  edit(personId: number, version: number, form: PersonForm): Observable<Person> {
    return this.http
      .put<Person>(`${this.url(this.sheet())}/${personId}`, { ...form, version }, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  /** Retire the person from a date (yyyy-MM-dd); without one, from the sheet's today. */
  retire(personId: number, from: string | null): Observable<Person> {
    return this.http
      .post<Person>(`${this.url(this.sheet())}/${personId}/retire`, { from }, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  /** Put the person on hold from a date (yyyy-MM-dd; without one, the sheet's today) to a date (none: open-ended). */
  hold(personId: number, from: string | null, to: string | null): Observable<Person> {
    return this.http
      .post<Person>(`${this.url(this.sheet())}/${personId}/hold`, { from, to }, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  /** Name another person on the sheet as the person's patron; refused (409) for one already named. */
  addPatron(personId: number, patronId: number): Observable<Person> {
    return this.http
      .post<Person>(`${this.url(this.sheet())}/${personId}/patrons`, { patronId }, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  private sheet(): string {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return id;
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }
}

