export interface Rate {
  grade: Grade;
  /** A percent as text with two decimals, e.g. "12.50". */
  pct: string;
  /** The first date (yyyy-MM-dd) the rate applies on; null when it applies from the beginning of time. */
  from: string | null;
}

// The active sheet's rates, at most one per grade and from-date. A claim uses its grade's rate with
// the latest from-date on or before the claim's date (a rate with none applies from the beginning of
// time); a claim dated before every rate of its grade has none.
@Injectable({ providedIn: 'root' })
export class RatesService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Rate[]>([]);

  readonly rates = this.list.asReadonly();

  /** Each grade's rate in force on the sheet's today; a grade with none then is absent. */
  readonly current = computed(() => {
    const today = this.sheets.today();
    const out = new Map<Grade, Rate>();
    if (today === null) return out;
    for (const g of GRADES) {
      const r = inForce(this.list(), g, today);
      if (r) out.set(g, r);
    }
    return out;
  });

  /** Each grade's rate in force on the sheet's today, in hundredths of a percent; a grade with none then is absent. */
  readonly byGrade = computed(() => {
    const out = new Map<Grade, number>();
    for (const [g, r] of this.current()) out.set(g, hundredths(r.pct));
    return out;
  });

  /** The grade's rate in force on a date (yyyy-MM-dd), in hundredths of a percent; undefined when none. */
  rateOn(grade: Grade, date: string): number | undefined {
    const r = inForce(this.list(), grade, date);
    return r ? hundredths(r.pct) : undefined;
  }

  /** Re-read the active sheet's rates from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Rate[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((rates) => {
        if (this.sheets.sheetId() === id) this.list.set(rates);
      }));
  }

  /** Set a grade's rate from a date (null: from the beginning of time), replacing the one it had for that from-date. */
  set(grade: Grade, pct: string, from: string | null): Observable<Rate> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .put<Rate>(`${this.url(id)}/${grade}`, { pct, from }, { headers: this.session.headers() })
      .pipe(tap((r) => this.list.update((all) => [
        ...all.filter((o) => o.grade !== r.grade || o.from !== r.from),
        r,
      ].sort(byGradeThenFrom))));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}

/** The grade's rate with the latest from-date on or before the date; undefined when none. */
function inForce(rates: readonly Rate[], grade: Grade, date: string): Rate | undefined {
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best;
}

function byGradeThenFrom(a: Rate, b: Rate): number {
  return a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '');
}

/** "12.50" as 1250. */
function hundredths(pct: string): number {
  const [whole, frac = ''] = pct.split('.');
  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
}

/**
 * Cents times a rate (in hundredths of a percent) divided by 100, in cents, rounded half to even (a
 * half goes to the even cent), or half up (away from zero) when `halfUp`. Worked in BigInt so it is
 * exact for any amount.
 */
export function due(cents: number, rate: number, halfUp = false): number {
  if (cents < 0) return -due(-cents, rate, halfUp);
  const product = BigInt(cents) * BigInt(rate);
  const q = product / 10000n;
  const r = product % 10000n;
  return Number(r > 5000n || (r === 5000n && (halfUp || q % 2n === 1n)) ? q + 1n : q);
}

export type Role = 'clerk' | 'steward';

export const ROLES: readonly Role[] = ['clerk', 'steward'];

export interface RoleEntry {
  user: string;
  role: Role;
}

interface SettingsView {
  /** Two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** Two decimals: a claim's live due is at least this. */
  floor: string;
  /** Days: a claim is due by its date plus these. */
  terms: number;
  /** Days: the terms of each grade that has its own (a grade left out uses the sheet's terms). */
  gradeTerms: Partial<Record<Grade, number>>;
  /** Two decimals: an overdue claim gains this percent of its figure for every full 30 days overdue. */
  latePct: string;
  /** yyyy-MM-dd; null when none is set (the sheet's today is the policy date). */
  policyDate: string | null;
  /** yyyy-MM-dd; null when off: claims opened take the sheet-wide numbers. */
  periodNumberingFrom: string | null;
}

/** The settings to save; one left out keeps its value. The clerk limit is '' for no limit. */
export interface SettingsChange {
  clerkLimit?: string;
  floor?: string;
  terms?: string;
  /** A grade's own terms; '' for the sheet's terms. */
  gradeTerms?: Partial<Record<Grade, string>>;
  latePct?: string;
  policyDate?: string;
  periodNumberingFrom?: string;
}

/** The floor a sheet starts with. */
const DEFAULT_FLOOR = '1.00';

/** The terms (days) a sheet starts with. */
const DEFAULT_TERMS = 14;

/** The late percent a sheet starts with. */
const DEFAULT_LATE_PCT = '0.00';

// The active sheet's settings and the roles it gives user names. A name with no role is a clerk; a
// clerk may settle a claim only when its due is at or below the clerk limit (none: no limit), a
// steward any claim. A claim's live due is at least the floor; it is due by its date plus the terms of its
// person's grade (the sheet's terms for a grade without its own) when it was created;
// an overdue one gains the late percent of its figure for every full 30 days overdue. A claim dated
// before the policy date (none: the sheet's today) rounds its live figures half up, else half to even.
// While the period numbering from-date is set and the sheet's today is on or after it, a claim opened
// is numbered within its period (<period name>-<n>; X-<n> in no period).
@Injectable({ providedIn: 'root' })
export class SettingsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly limit = signal<string | null>(null);
  private readonly floorValue = signal<string>(DEFAULT_FLOOR);
  private readonly termsValue = signal<number>(DEFAULT_TERMS);
  private readonly gradeTermsValue = signal<Partial<Record<Grade, number>>>({});
  private readonly latePctValue = signal<string>(DEFAULT_LATE_PCT);
  private readonly policyDateValue = signal<string | null>(null);
  private readonly periodNumberingFromValue = signal<string | null>(null);
  private readonly list = signal<RoleEntry[]>([]);

  readonly clerkLimit = this.limit.asReadonly();
  readonly floor = this.floorValue.asReadonly();
  /** The floor in cents. */
  readonly floorCents = computed(() => cents(this.floorValue()));
  /** The terms in days. */
  readonly terms = this.termsValue.asReadonly();
  /** The terms in days of each grade that has its own. */
  readonly gradeTerms = this.gradeTermsValue.asReadonly();
  readonly latePct = this.latePctValue.asReadonly();
  /** The late percent in hundredths of a percent. */
  readonly latePctHundredths = computed(() => cents(this.latePctValue()));
  /** The policy date set (yyyy-MM-dd); null when none. */
  readonly policyDate = this.policyDateValue.asReadonly();
  /** The policy date in force: the one set, else the sheet's today (null: none loaded). */
  readonly policyInForce = computed(() => this.policyDateValue() ?? this.sheets.today());
  /** The period numbering from-date (yyyy-MM-dd); null when off. */
  readonly periodNumberingFrom = this.periodNumberingFromValue.asReadonly();
  readonly roles = this.list.asReadonly();
  /** What an overdue claim's late charge follows now. */
  readonly late = computed<LateTerms>(() => ({
    today: this.sheets.today(), pct: this.latePctHundredths(),
  }));

  /** Re-read the active sheet's settings and roles from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.limit.set(null);
      this.floorValue.set(DEFAULT_FLOOR);
      this.termsValue.set(DEFAULT_TERMS);
      this.gradeTermsValue.set({});
      this.latePctValue.set(DEFAULT_LATE_PCT);
      this.policyDateValue.set(null);
      this.periodNumberingFromValue.set(null);
      this.list.set([]);
      return of(null);
    }
    const headers = this.session.headers();
    return forkJoin([
      this.http.get<SettingsView>(`${this.url(id)}/settings`, { headers }),
      this.http.get<RoleEntry[]>(`${this.url(id)}/roles`, { headers }),
    ]).pipe(tap(([settings, roles]) => {
      if (this.sheets.sheetId() !== id) return;
      this.set(settings);
      this.list.set(roles);
    }));
  }

  /** Save the settings given (the others keep their values). */
  save(change: SettingsChange): Observable<SettingsView> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .put<SettingsView>(`${this.url(id)}/settings`, change, { headers: this.session.headers() })
      .pipe(tap((s) => this.set(s)));
  }

  private set(settings: SettingsView): void {
    this.limit.set(settings.clerkLimit);
    this.floorValue.set(settings.floor);
    this.termsValue.set(settings.terms);
    this.gradeTermsValue.set(settings.gradeTerms);
    this.latePctValue.set(settings.latePct);
    this.policyDateValue.set(settings.policyDate);
    this.periodNumberingFromValue.set(settings.periodNumberingFrom);
  }

  /** Give a user name a role, replacing the one it had; refused for any role but clerk or steward. */
  setRole(user: string, role: string): Observable<RoleEntry> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .put<RoleEntry>(`${this.url(id)}/roles`, { user, role }, { headers: this.session.headers() })
      .pipe(tap((r) => this.list.update((all) => [...all.filter((o) => o.user !== r.user), r]
        .sort((a, b) => a.user.localeCompare(b.user)))));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** The first date (yyyy-MM-dd) in the period. */
  from: string;
  /** The last date (yyyy-MM-dd) in the period. */
  to: string;
  /** Closed: its due-total is fixed and no claim dated in it can change. */
  closed: boolean;
  /** The due-total fixed when it closed (two decimals); null while open. */
  closedTotal: string | null;
}

export interface PeriodForm {
  name: string;
  from: string;
  to: string;
}

// The active sheet's periods, by from-date. No two overlap, so a date (and the claim dated on it)
// belongs to at most one.
@Injectable({ providedIn: 'root' })
export class PeriodsService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Period[]>([]);

  readonly periods = this.list.asReadonly();

  /** The period whose dates contain the date (yyyy-MM-dd); undefined when none does. */
  periodOn(date: string): Period | undefined {
    return this.list().find((p) => p.from <= date && date <= p.to);
  }

  /** Re-read the active sheet's periods from the store. */
  reload(): Observable<unknown> {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return of(null);
    }
    return this.http
      .get<Period[]>(this.url(id), { headers: this.session.headers() })
      .pipe(tap((periods) => {
        if (this.sheets.sheetId() === id) this.list.set(periods);
      }));
  }

  /** Add a period; refused when it ends before it starts, reuses a name or overlaps another. */
  add(form: PeriodForm): Observable<Period> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .post<Period>(this.url(id), form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => [...all, p].sort((a, b) => a.from.localeCompare(b.from)))));
  }

  /** Close a period, fixing its due-total; refused when it is already closed. */
  close(periodId: number): Observable<Period> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .post<Period>(`${this.url(id)}/${periodId}/close`, null, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((q) => (q.id === p.id ? p : q)))));
  }

  /** Reopen a closed period, making its due-total live again; refused unless a steward reopens a closed one. */
  reopen(periodId: number): Observable<Period> {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return this.http
      .post<Period>(`${this.url(id)}/${periodId}/reopen`, null, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((q) => (q.id === p.id ? p : q)))));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }
}
